css:
.loader {
  position: relative;
  width: 52px;
  height: 52px;
  animation: spin 0.9s ease-in-out infinite;
}
.loader::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
  border-radius: 50%;
  border: 3px solid #6366f1;
  box-sizing: border-box;
  background: #e0e7ff;
  z-index: 2;
}
.loader i {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 16px;
  height: 16px;
  margin: -8px 0 0 -8px;
  border-radius: 50%;
  background: #6366f1;
}
.loader i:nth-child(1) { transform: rotate(0deg) translateY(-17px); }
.loader i:nth-child(2) { transform: rotate(120deg) translateY(-17px); }
.loader i:nth-child(3) { transform: rotate(240deg) translateY(-17px); }
@keyframes spin { to { transform: rotate(360deg); } }
